-- Enriquecimiento de preguntas ti-estado-273
-- Fuentes: Manual Específico de Funciones PGN v.10; Temario Convocatoria 273-2026 (Asesor 1AS-21).
-- Criterio: se conservan las normas reales del marco TIC del Estado; se dejan vacíos los artículos
-- que no pueden verificarse contra los documentos entregados (decretos/leyes TIC no suministrados).
-- Se reemplazan dos preguntas sobre OWASP por contenido anclado al Manual de Funciones de la PGN.

UPDATE preguntas SET norma='Decreto 089/2018', articulo='', explicacion='El MinTIC lidera la formulación y orientación de la política de Gobierno Digital en Colombia. Este conocimiento es clave para el Asesor en TIC de la PGN, cuyas función incluye orientar la transformación digital y la adopción de soluciones de tecnologías de la información.' WHERE id=261;

UPDATE preguntas SET norma='Marco de Arquitectura Empresarial del Estado', articulo='', explicacion='El Marco de Arquitectura Empresarial del Estado (MAE) busca que las entidades públicas diseñen sus soluciones de TI de manera integral, alineando procesos, datos, aplicaciones e infraestructura con los fines institucionales. El Manual de Funciones de la PGN señala que el Asesor en TIC debe actuar en el marco del modelo de arquitectura empresarial del Estado.' WHERE id=262;

UPDATE preguntas SET norma='Decreto 1519/2013', articulo='', explicacion='El Decreto 1519 de 2013 reglamenta el Marco de Interoperabilidad para el Estado Colombiano, estableciendo lineamientos para el intercambio de información entre entidades públicas. El Manual de Funciones de la PGN destaca la necesidad de asegurar la interoperabilidad en los proyectos de servicios ciudadanos digitales.' WHERE id=263;

UPDATE preguntas SET norma='Modelo de Seguridad y Privacidad de la Información (MSPI)', articulo='', explicacion='MSPI significa Modelo de Seguridad y Privacidad de la Información. Orienta a las entidades públicas en la gestión de riesgos de seguridad y privacidad de sus activos de información. El Manual de Funciones de la PGN lo vincula con el habilitador de seguridad y privacidad de la información de la Política de Gobierno Digital.' WHERE id=264;

UPDATE preguntas SET norma='Decreto 1519/2013', articulo='', explicacion='La interoperabilidad semántica garantiza que el significado de la información intercambiada sea comprensible y utilizable por los sistemas y actores involucrados, mediante vocabularios y modelos de datos comunes. Es uno de los tipos de interoperabilidad definidos en el Marco de Interoperabilidad para el Estado Colombiano.' WHERE id=265;

UPDATE preguntas SET norma='Ley 1955/2019', articulo='', explicacion='La Ley 1955 de 2019, correspondiente al Plan Nacional de Desarrollo 2018-2022, creó el Ministerio de Tecnologías de la Información y las Comunicaciones (MinTIC), asumiendo las funciones de la extinta Agencia Presidencial de TIC y liderando la política sectorial de TIC y Gobierno Digital.' WHERE id=266;

UPDATE preguntas SET norma='Decreto 089/2018', articulo='', explicacion='El Decreto 089 de 2018 establece principios como transparencia, eficiencia, accesibilidad, inclusión, seguridad y participación ciudadana para orientar la gestión digital del Estado colombiano. Estos principios guían la adopción de soluciones de TI en las entidades públicas, incluida la PGN.' WHERE id=267;

UPDATE preguntas SET norma='Ley 1581/2012', articulo='', explicacion='La Ley 1581 de 2012 es la norma general de protección de datos personales en Colombia. Desarrolla el derecho constitucional al hábeas data y establece deberes para los responsables del tratamiento de datos personales en el sector público y privado.' WHERE id=269;

UPDATE preguntas SET norma='Ley 1581/2012', articulo='', explicacion='El principio de finalidad establece que el tratamiento de datos personales debe realizarse para una finalidad legítima, informada y previamente autorizada por el titular, sin desviarse de dicho propósito. Es uno de los principios de la protección de datos personales en Colombia.' WHERE id=270;

UPDATE preguntas SET norma='Decreto 1377/2013', articulo='', explicacion='El Decreto 1377 de 2013 reglamenta parcialmente la Ley 1581 de 2012 en materia de autorización para el tratamiento de datos sensibles. Exige autorización previa, expresa e informada del titular, salvo las excepciones legales expresamente previstas.' WHERE id=271;

UPDATE preguntas SET norma='Ley 527/1999', articulo='', explicacion='La Ley 527 de 1999 regula el comercio electrónico, la firma digital y los mensajes de datos en Colombia, reconociendo su validez legal y los requisitos para su uso en el ámbito público y privado.' WHERE id=272;

UPDATE preguntas SET norma='Decreto 1078/2015', articulo='', explicacion='El Decreto 1078 de 2015 es el decreto único reglamentario del sector de TIC. Compila y actualiza las normas reglamentarias del sector, incluyendo disposiciones relacionadas con la Ley 1341 de 2009, facilitando su aplicación por las entidades públicas.' WHERE id=273;

UPDATE preguntas SET norma='Modelo de Seguridad y Privacidad de la Información (MSPI)', articulo='', explicacion='El MSPI proporciona lineamientos para que las entidades públicas identifiquen, evalúen y traten los riesgos de seguridad y privacidad de la información, protegiendo los activos de datos del Estado. El Manual de Funciones de la PGN lo vincula con el habilitador de seguridad y privacidad de la información de la Política de Gobierno Digital.' WHERE id=274;

UPDATE preguntas SET norma='Ley 1712/2014', articulo='', explicacion='La Ley 1712 de 2014 regula el derecho fundamental de acceso a la información pública en Colombia y establece obligaciones de publicación activa, incluyendo la apertura de datos en formatos abiertos. Esto complementa la política de Gobierno Digital al garantizar transparencia en el uso de las TIC por parte del Estado.' WHERE id=276;

UPDATE preguntas SET norma='Decreto 1519/2013', articulo='', explicacion='La interoperabilidad técnica se refiere a la capacidad de los sistemas informáticos para conectarse, comunicarse e intercambiar datos mediante estándares y protocolos comunes definidos por el Marco de Interoperabilidad para el Estado Colombiano.' WHERE id=277;

UPDATE preguntas SET norma='Ley 1955/2019', articulo='', explicacion='La Ley 1955 de 2019, del Plan Nacional de Desarrollo, planteó la transformación digital del Estado para mejorar la eficiencia pública, cerrar brechas digitales y facilitar el acceso de los ciudadanos a servicios públicos mediante el uso de las TIC.' WHERE id=278;

UPDATE preguntas SET norma='Decreto 1232/2020', articulo='', explicacion='El Decreto 1232 de 2020 define incidente de seguridad digital como un evento adverso que afecta la confidencialidad, integridad, disponibilidad o trazabilidad de la información, y requiere respuesta coordinada por las entidades públicas.' WHERE id=279;

UPDATE preguntas SET norma='Ley 1341/2009', articulo='', explicacion='La Ley 1341 de 2009 declara las tecnologías de la información y las comunicaciones como servicio público esencial en Colombia. Esta declaratoria busca garantizar el acceso y uso de las TIC en todo el territorio nacional, desarrollada reglamentariamente por el Decreto 1078 de 2015.' WHERE id=280;
